const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-image-description-backfill", node: "Code: Init Run" } });

// Window limits per schedule (seconds). Webhook may override for ad-hoc test runs.
const WINDOW_LIMITS = {
  'Schedule Trigger: 23:30': 8100,  // 2h15min
  'Schedule Trigger: 06:00': 6300   // 1h45min
};
const DEFAULT_TEST_LIMIT_SECONDS = 300; // fallback for ad-hoc webhook runs without an explicit override

const item = $input.first().json;

// A self-invocation (Execute Workflow Trigger) always carries an explicit
// window_start + max_runtime_seconds from the parent run — continue that
// window unchanged rather than starting a new one.
if (item.window_start !== undefined && item.max_runtime_seconds !== undefined) {
  logger.info(`[image-description-backfill] Continuation run, window_start=${item.window_start}, max_runtime_seconds=${item.max_runtime_seconds}`);
  return [{ json: {
    window_start: item.window_start,
    max_runtime_seconds: item.max_runtime_seconds,
    lock_owner: item.lock_owner,
    is_continuation: true,
    _from_webhook: item._from_webhook === true
  } }];
}

// First run of a window: determine which trigger fired and the limit that applies.
let maxRuntimeSeconds;
let fromWebhook = false;

// Determine the actual firing trigger via node names present in the execution.
let firedNode = null;
try {
  if ($('Schedule Trigger: 23:30').first()) firedNode = 'Schedule Trigger: 23:30';
} catch(e) {}
try {
  if (!firedNode && $('Schedule Trigger: 06:00').first()) firedNode = 'Schedule Trigger: 06:00';
} catch(e) {}
try {
  if (!firedNode && $('Webhook: POST /image-description-backfill').first()) firedNode = 'Webhook: POST /image-description-backfill';
} catch(e) {}

if (firedNode && WINDOW_LIMITS[firedNode]) {
  maxRuntimeSeconds = WINDOW_LIMITS[firedNode];
} else {
  // Webhook (ad-hoc test) run: read override from body/query, same pattern as PROJ-92.
  fromWebhook = true;
  let body = {}, query = {};
  try {
    const webhookItem = $('Webhook: POST /image-description-backfill').first().json;
    body = webhookItem.body || {};
    query = webhookItem.query || {};
  } catch(e) {}
  const rawMax = body.max_runtime_seconds !== undefined ? body.max_runtime_seconds : query.max_runtime_seconds;
  const parsedMax = parseInt(rawMax, 10);
  maxRuntimeSeconds = (!isNaN(parsedMax) && parsedMax > 0) ? parsedMax : DEFAULT_TEST_LIMIT_SECONDS;
}

const windowStart = Date.now();
logger.info(`[image-description-backfill] First run of window, trigger=${firedNode || 'webhook'}, max_runtime_seconds=${maxRuntimeSeconds}, window_start=${windowStart}`);

return [{ json: {
  window_start: windowStart,
  max_runtime_seconds: maxRuntimeSeconds,
  is_continuation: false,
  _from_webhook: fromWebhook
} }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-image-description-backfill", node: "Code: Acquire/Renew Lock" } });
const redis = require('redis');
const crypto = require('crypto');

const LOCK_KEY = 'alice:dms:image-description-backfill:lock:run';
const LOCK_TTL_MS = 900000; // 15 min, well above a single 50-image batch (~25 min worst case at 30s/image, renewed every batch)

const item = $input.first().json;
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });

if (!item.is_continuation) {
  // First run of a window: fail-closed. Two overlapping chains would double up
  // Ollama load on a server with n_slots=1 - the core reason this lock exists.
  const ownerToken = crypto.randomUUID();
  let acquired = false;
  try {
    await client.connect();
    const res = await client.set(LOCK_KEY, JSON.stringify({ owner: ownerToken, started_at: new Date().toISOString() }), { NX: true, PX: LOCK_TTL_MS });
    acquired = (res === 'OK');
  } catch(e) {
    logger.info(`[image-description-backfill] Lock acquire error: ${e.message} - failing closed (skip run)`);
    acquired = false;
  } finally {
    await client.quit().catch(() => {});
  }
  return [{ json: { ...item, lock_owner: acquired ? ownerToken : null, _lock_acquired: acquired } }];
}

// Continuation (self-invocation): renew the same lock, fail-open. No second
// chain can start in the meantime without seeing this lock (even if expired,
// TTL is generous relative to batch time), so a Redis hiccup here must not
// abort an already-successfully-started, multi-hour chain.
const owner = item.lock_owner;
const RENEW_SCRIPT = `
local raw = redis.call('GET', KEYS[1])
if not raw then return 0 end
local ok, data = pcall(cjson.decode, raw)
if not ok or data.owner ~= ARGV[1] then return 0 end
redis.call('SET', KEYS[1], raw, 'PX', ARGV[2])
return 1
`;
try {
  await client.connect();
  await client.eval(RENEW_SCRIPT, { keys: [LOCK_KEY], arguments: [owner, String(LOCK_TTL_MS)] });
} catch(e) {
  logger.info(`[image-description-backfill] Lock renew error: ${e.message} - continuing fail-open`);
} finally {
  await client.quit().catch(() => {});
}
return [{ json: { ...item, _lock_acquired: true } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-image-description-backfill", node: "Code: Skip (Locked)" } });
logger.info('[image-description-backfill] Run skipped: another window chain is already in progress (lock held)');
const run = $input.first().json;
return [{ json: { processed: 0, updated: 0, still_failed: 0, remaining: null, skipped: true, reason: 'locked', _from_webhook: run._from_webhook === true } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-image-description-backfill", node: "Code: Fetch Failed Batch" } });
const axios = require('axios');

// Reset per-run counters (workflow static data persists across executions, so it must be zeroed at the start of every run)
const staticData = $getWorkflowStaticData('global');
staticData.updated = 0;
staticData.still_failed = 0;

const WEAVIATE = 'http://weaviate:8080';
const LIMIT = 50;
const gql = `{ Get { Image(where: { path: ["extraction_failed"], operator: Equal, valueBoolean: true }, limit: ${LIMIT}) { _additional { id } file_path additionalPaths } } }`;

let results = [];
try {
  const r = await axios.post(`${WEAVIATE}/v1/graphql`, { query: gql }, {
    headers: { 'Content-Type': 'application/json' },
    timeout: 30000
  });
  if (r.data?.errors) {
    logger.warn(`[image-description-backfill] GraphQL error: ${JSON.stringify(r.data.errors)}`);
  } else {
    results = r.data?.data?.Get?.Image || [];
  }
} catch (e) {
  logger.warn(`[image-description-backfill] Fetch failed: ${e.message}`);
}

logger.info(`[image-description-backfill] Found ${results.length} image(s) with extraction_failed=true`);

const run = $('Code: Acquire/Renew Lock').first().json;

if (results.length === 0) {
  return [{ json: { _empty: true, window_start: run.window_start, max_runtime_seconds: run.max_runtime_seconds, lock_owner: run.lock_owner, _from_webhook: run._from_webhook } }];
}

return results.map(doc => ({
  json: {
    weaviate_uuid: doc._additional?.id,
    file_path: doc.file_path || null,
    additionalPaths: doc.additionalPaths || [],
    _empty: false,
    window_start: run.window_start,
    max_runtime_seconds: run.max_runtime_seconds,
    lock_owner: run.lock_owner,
    _from_webhook: run._from_webhook
  }
}));

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-image-description-backfill", node: "Code: Empty Summary" } });
