const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-image-description-backfill", node: "Code: Resolve & Read Image" } });
const fs = require('fs');
const item = $input.first().json;
const candidates = [item.file_path, ...(item.additionalPaths || [])].filter(Boolean);

let resolvedPath = null;
for (const p of candidates) {
  try {
    if (fs.existsSync(p)) { resolvedPath = p; break; }
  } catch (e) {}
}

if (!resolvedPath) {
  logger.warn(`[image-description-backfill] No readable path for ${item.weaviate_uuid}`);
  return [{ json: { weaviate_uuid: item.weaviate_uuid, _read_ok: false } }];
}

try {
  const buf = fs.readFileSync(resolvedPath);
  return [{ json: { weaviate_uuid: item.weaviate_uuid, resolved_path: resolvedPath, image_b64: buf.toString('base64'), _read_ok: true } }];
} catch (e) {
  logger.warn(`[image-description-backfill] Read failed for ${resolvedPath}: ${e.message}`);
  return [{ json: { weaviate_uuid: item.weaviate_uuid, _read_ok: false } }];
}

