const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-image-description-backfill", node: "Code: Log PATCH Result" } });
const resp = $input.first().json;
const statusCode = resp.statusCode || 0;
const staticData = $getWorkflowStaticData('global');
if (statusCode >= 200 && statusCode < 300) {
  staticData.updated = (staticData.updated || 0) + 1;
  return [{ json: { result: 'updated' } }];
} else {
  staticData.still_failed = (staticData.still_failed || 0) + 1;
  logger.warn(`[image-description-backfill] PATCH failed (HTTP ${statusCode})`);
  return [{ json: { result: 'still_failed', reason: 'patch_failed' } }];
}

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-image-description-backfill", node: "Code: Time Check" } });
const run = $('Code: Fetch Failed Batch').first().json;
const elapsedSeconds = (Date.now() - run.window_start) / 1000;
const timeLimitReached = elapsedSeconds >= run.max_runtime_seconds;
if (timeLimitReached) {
  logger.info(`[image-description-backfill] Window time limit reached (elapsed=${Math.round(elapsedSeconds)}s, limit=${run.max_runtime_seconds}s) - leaving loop, in-flight image already completed`);
}
return [{ json: { ...$input.first().json, _time_limit_reached: timeLimitReached } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-image-description-backfill", node: "Code: Summary" } });
const staticData = $getWorkflowStaticData('global');
const updated = staticData.updated || 0;
const still_failed = staticData.still_failed || 0;
const processed = updated + still_failed;

const axios = require('axios');
let remaining = null;
try {
  const gql = `{ Aggregate { Image(where: { path: ["extraction_failed"], operator: Equal, valueBoolean: true }) { meta { count } } } }`;
  const r = await axios.post('http://weaviate:8080/v1/graphql', { query: gql }, {
    headers: { 'Content-Type': 'application/json' },
    timeout: 30000
  });
  remaining = r.data?.data?.Aggregate?.Image?.[0]?.meta?.count ?? null;
} catch (e) {
  logger.warn(`[image-description-backfill] Remaining count query failed: ${e.message}`);
}

const summary = { processed, updated, still_failed, remaining };
logger.info(`[image-description-backfill] Summary: ${JSON.stringify(summary)}`);
return [{ json: summary }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-image-description-backfill", node: "Code: Check Continue" } });
const summary = $input.first().json;
const run = $('Code: Fetch Failed Batch').first().json;
const BUFFER_SECONDS = 300; // 5 min safety buffer before the window limit

const elapsedSeconds = (Date.now() - run.window_start) / 1000;
const timeRemaining = run.max_runtime_seconds - elapsedSeconds;
const hasMoreImages = (summary.remaining || 0) > 0;
const enoughTimeForAnotherBatch = timeRemaining >= BUFFER_SECONDS;

const shouldContinue = hasMoreImages && enoughTimeForAnotherBatch;
logger.info(`[image-description-backfill] Check Continue: remaining=${summary.remaining}, time_remaining=${Math.round(timeRemaining)}s, shouldContinue=${shouldContinue}`);

return [{ json: { ...summary, window_start: run.window_start, max_runtime_seconds: run.max_runtime_seconds, lock_owner: run.lock_owner, _from_webhook: run._from_webhook, _should_continue: shouldContinue } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-image-description-backfill", node: "Code: Release Lock" } });
const redis = require('redis');
const run = $('Code: Fetch Failed Batch').first().json;
const owner = run.lock_owner;

if (owner) {
  const LOCK_KEY = 'alice:dms:image-description-backfill:lock:run';
  const RELEASE_SCRIPT = `
local raw = redis.call('GET', KEYS[1])
if not raw then return 0 end
local ok, data = pcall(cjson.decode, raw)
if not ok or data.owner ~= ARGV[1] then return 0 end
redis.call('DEL', KEYS[1])
return 1
`;
  let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
  const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
  try {
    await client.connect();
    await client.eval(RELEASE_SCRIPT, { keys: [LOCK_KEY], arguments: [owner] });
  } catch(e) {
    logger.info(`[image-description-backfill] Lock release error: ${e.message}`);
  } finally {
    await client.quit().catch(() => {});
  }
}

return [{ json: { ...$input.first().json, _from_webhook: run._from_webhook === true } }];
